+    // missing fields caused `serde_json` / `bincode` to error.
+    let old_json = r#"{
+        "channel_count": 3,
+        "self_weight": 0.9,
+        "cross_weight": -0.15,
+        "threshold": 0.22,
+        "leak": 0.12,
+        "routing_timesteps": 16,
+        "min_fire_rate": 0.1875
